package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.provider.Settings;
import android.text.InputFilter;
import android.text.format.Formatter;
import android.util.DisplayMetrics;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.function.Consumer;

/** Windows-style specification cards, populated only with data Android exposes. */
final class TenAbout {
 static void add(LinearLayout body,DesktopStore store,int width,Consumer<String> open){
  Context c=body.getContext();LinkedHashMap<String,String> device=new LinkedHashMap<>(),system=new LinkedHashMap<>();
  String name=store.prefs.getString("ten_device_name",Build.MODEL);String cpu=Build.VERSION.SDK_INT>=31?Build.SOC_MANUFACTURER+" "+Build.SOC_MODEL:Build.HARDWARE;
  if(cpu.trim().isEmpty()||cpu.contains("unknown"))cpu=Build.HARDWARE;
  ActivityManager manager=c.getSystemService(ActivityManager.class);ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();if(manager!=null)manager.getMemoryInfo(memory);
  String ram=memory.totalMem>0?Formatter.formatFileSize(c,memory.totalMem):"Unavailable";String storage="Unavailable",storageDetail="";
  try{StatFs stat=new StatFs(Environment.getDataDirectory().getPath());storage=Formatter.formatFileSize(c,stat.getTotalBytes());storageDetail=Formatter.formatFileSize(c,stat.getAvailableBytes())+" available · shared data volume";}catch(RuntimeException ignored){}
  String graphics=manager==null?"Unavailable":"OpenGL ES "+manager.getDeviceConfigurationInfo().getGlEsVersion();
  int vulkan=0;for(FeatureInfo f:c.getPackageManager().getSystemAvailableFeatures())if("android.hardware.vulkan.version".equals(f.name))vulkan=f.version;
  String gpuDetail=vulkan==0?"Android graphics capability":"Vulkan "+(vulkan>>22)+"."+((vulkan>>12)&1023);
  LinearLayout intro=Aero.column(c);TextView notice=Aero.text(c,"Device security",18,Aero.INK);intro.addView(notice);TextView security=Aero.text(c,"Security patch: "+value(Build.VERSION.SECURITY_PATCH)+"\nReview protection and updates in Android settings.",12,0xff666666);security.setPadding(0,dp(c,12),0,dp(c,22));intro.addView(security);body.addView(intro);
  LinearLayout layout=new LinearLayout(c);LinearLayout main=Aero.column(c);layout.addView(main,new LinearLayout.LayoutParams(0,-2,1));body.addView(layout,new LinearLayout.LayoutParams(-1,-2));
  int available=width>=dp(c,850)?width-dp(c,220):width;int columns=available>=dp(c,650)?4:available>=dp(c,200)?2:1;
  GridLayout cards=new GridLayout(c);cards.setColumnCount(columns);String[][] summaries={{"Installed RAM",ram,"Physical memory reported by Android"},{"Processor",cpu,Runtime.getRuntime().availableProcessors()+" logical CPU cores"},{"Graphics",graphics,gpuDetail},{"Storage",storage,storageDetail}};
  for(int i=0;i<summaries.length;i++){LinearLayout card=Aero.column(c);Aero.pad(card,12);card.setBackground(Aero.panel(c,0xffffffff,0xffffffff,0,0xffd6d6d6));card.addView(Aero.text(c,summaries[i][0],11,0xff666666));TextView primary=Aero.text(c,summaries[i][1],15,Aero.INK);Aero.bold(primary);primary.setPadding(0,dp(c,12),0,dp(c,8));card.addView(primary,new LinearLayout.LayoutParams(-1,0,1));card.addView(Aero.text(c,summaries[i][2],10,0xff666666));GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/columns),GridLayout.spec(i%columns,1f));p.width=0;p.height=dp(c,146);p.setMargins(0,0,dp(c,6),dp(c,6));cards.addView(card,p);}main.addView(cards,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout identity=Aero.column(c);Aero.pad(identity,14);identity.setBackgroundColor(0xfff0f0f0);identity.addView(Aero.text(c,name,17,Aero.INK));identity.addView(Aero.text(c,Build.MANUFACTURER+" "+Build.MODEL,12,0xff666666));identity.addView(Aero.button(c,"Rename this device",()->{EditText input=new EditText(c);input.setSingleLine();input.setText(name);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});Aero.dialog(c).setTitle("Rename this device").setMessage("This name is used inside Nth Desktop Ten.").setView(input).setPositiveButton("Save",(d,w)->{String n=input.getText().toString().trim();if(!n.isEmpty()){store.prefs.edit().putString("ten_device_name",n).apply();if(c instanceof MainActivity)((MainActivity)c).applyTenAppearance();}}).setNegativeButton("Cancel",null).show();}));main.addView(identity);
  device.put("Device name",name);device.put("Manufacturer",Build.MANUFACTURER);device.put("Model",Build.MODEL);device.put("Processor",cpu);device.put("CPU cores",String.valueOf(Runtime.getRuntime().availableProcessors()));device.put("Installed RAM",ram);device.put("Available RAM",Formatter.formatFileSize(c,memory.availMem));device.put("Graphics API",graphics+" · "+gpuDetail);device.put("Storage",storage+" · "+storageDetail);device.put("System type",String.join(", ",Build.SUPPORTED_ABIS));device.put("Board / hardware",Build.BOARD+" / "+Build.HARDWARE);
  DisplayMetrics metrics=c.getResources().getDisplayMetrics();DisplayMetrics physical=new DisplayMetrics();Display display=((android.app.Activity)c).getWindowManager().getDefaultDisplay();display.getRealMetrics(physical);device.put("Display",physical.widthPixels+" × "+physical.heightPixels+" pixels · "+metrics.densityDpi+" dpi");device.put("Refresh rate",String.format(Locale.getDefault(),"%.1f Hz",display.getRefreshRate()));
  PackageManager pm=c.getPackageManager();device.put("Pen and touch",(pm.hasSystemFeature(PackageManager.FEATURE_TOUCHSCREEN_MULTITOUCH)?"Multitouch":pm.hasSystemFeature(PackageManager.FEATURE_TOUCHSCREEN)?"Touchscreen":"No touchscreen reported")+(pm.hasSystemFeature("android.hardware.touchscreen.stylus")?" · Stylus supported":""));
  system.put("Edition","Nth Desktop Ten for Android");system.put("Launcher version",BuildConfig.VERSION_NAME+" ("+BuildConfig.VERSION_CODE+")");system.put("Package",BuildConfig.APPLICATION_ID);system.put("Android version",Build.VERSION.RELEASE+" · API "+Build.VERSION.SDK_INT);system.put("Security patch",value(Build.VERSION.SECURITY_PATCH));system.put("Build number",Build.DISPLAY);system.put("Build ID",Build.ID);system.put("Build fingerprint",Build.FINGERPRINT);system.put("Bootloader",value(Build.BOOTLOADER));system.put("Kernel",System.getProperty("os.version","Unavailable"));system.put("System uptime",android.text.format.DateUtils.formatElapsedTime(SystemClock.elapsedRealtime()/1000));system.put("Locale",Locale.getDefault().toLanguageTag());system.put("Time zone",TimeZone.getDefault().getID());
  try{PackageInfo info=pm.getPackageInfo(c.getPackageName(),0);system.put("Installed on",java.text.DateFormat.getDateTimeInstance().format(new Date(info.firstInstallTime)));system.put("Updated on",java.text.DateFormat.getDateTimeInstance().format(new Date(info.lastUpdateTime)));}catch(PackageManager.NameNotFoundException ignored){}
  specifications(main,"Device specifications",device);specifications(main,"Android & launcher specifications",system);
  TextView scope=Aero.text(c,"An independent Android launcher inspired by Windows 10. Device values come from this phone; graphics describes supported APIs. Android does not expose PC product keys, RAM type or dedicated video memory here.",11,0xff666666);scope.setPadding(0,dp(c,16),0,dp(c,16));main.addView(scope);
  LinearLayout related=Aero.column(c);if(width>=dp(c,850)){LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(dp(c,200),-2);rp.leftMargin=dp(c,22);layout.addView(related,rp);}else main.addView(related);related.addView(Aero.text(c,"Related settings",15,Aero.INK));for(String[] link:new String[][]{{"Device settings","setting:android:device"},{"Storage","ten-setting:storage"},{"Apps & features","ten-setting:installed"},{"Display","ten-setting:display"},{"Backup","ten-setting:backup"}}){TextView b=TenStyle.command(c,link[0],()->open.accept(link[1]));b.setTextColor(0xff0078d7);TenAppearance.accentText(b);related.addView(b);}
 }
 private static void specifications(LinearLayout parent,String title,LinkedHashMap<String,String> values){Context c=parent.getContext();LinearLayout panel=Aero.column(c);panel.setPadding(dp(c,12),dp(c,8),dp(c,12),dp(c,12));panel.setBackground(Aero.panel(c,0xfff3f3f3,0xfff3f3f3,0,0xffdddddd));LinearLayout header=new LinearLayout(c);TextView heading=Aero.text(c,"ⓘ  "+title,14,Aero.INK);header.addView(heading,new LinearLayout.LayoutParams(0,dp(c,48),1));TextView copy=Aero.button(c,"Copy",()->{StringBuilder text=new StringBuilder(title+"\n");values.forEach((k,v)->text.append(k).append(": ").append(v).append('\n'));c.getSystemService(ClipboardManager.class).setPrimaryClip(ClipData.newPlainText(title,text));Toast.makeText(c,"Specifications copied",Toast.LENGTH_SHORT).show();});copy.setContentDescription("Copy "+title);header.addView(copy,new LinearLayout.LayoutParams(dp(c,64),dp(c,40)));panel.addView(header);LinearLayout details=Aero.column(c);details.setContentDescription(title);for(Map.Entry<String,String> entry:values.entrySet()){LinearLayout row=Aero.column(c);TextView label=Aero.text(c,entry.getKey(),12,Aero.INK);Aero.bold(label);row.addView(label);TextView value=Aero.text(c,value(entry.getValue()),12,0xff666666);value.setTextIsSelectable(true);value.setPadding(0,dp(c,5),0,dp(c,10));row.addView(value);details.addView(row);}panel.addView(details);heading.setFocusable(true);heading.setOnClickListener(v->details.setVisibility(details.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(c,8);parent.addView(panel,p);}
 private static String value(String s){return s==null||s.trim().isEmpty()?"Unavailable":s;}
 private static int dp(Context c,int n){return Aero.dp(c,n);}
 private TenAbout(){}
}
